import{_ as i,C as r,c,o as t,b0 as n,G as p,w as e,a as l}from"./chunks/framework.JcZxIv1X.js";const b="data:image/png;base64,",o="data:image/png;base64,",d="/computer-docs/assets/image-20251026201358121.DlfaX3G4.png",m="data:image/png;base64,",P=JSON.parse('{"title":"LV009-第9章-转移指令的原理","description":null,"frontmatter":{"title":"LV009-第9章-转移指令的原理","date":"2025-10-21T11:43:29.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/assembly/assembly/chapter/126b0eeb7bd93c428886a4f3","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-21T11:43:29.964Z","fulluuid":"28886a4f3aa640ccb7912e90ba1c01c7","useduuid":"28886a4f3"}},"headers":[],"relativePath":"sdoc/assembly/assembly/chapter/126b0eeb7bd93c428886a4f3.md","filePath":"sdoc/01-Assembly/10-汇编语言/01-各个章节/LV009-第9章-转移指令的原理.md","lastUpdated":1767424849000}'),u={name:"sdoc/assembly/assembly/chapter/126b0eeb7bd93c428886a4f3.md"};function h(g,s,v,A,x,C){const a=r("center");return t(),c("div",null,[s[3]||(s[3]=n(`<h1 id="lv009-第9章-转移指令的原理" tabindex="-1">LV009-第9章-转移指令的原理 <a class="header-anchor" href="#lv009-第9章-转移指令的原理" aria-label="Permalink to &quot;LV009-第9章-转移指令的原理&quot;">​</a></h1><p><strong>可以修改 IP，或同时修改 CS 和 IP 的指令统称为转移指令</strong>。概括地讲，转移指令就是可以控制 CPU 执行内存中某处代码的指令。</p><p>8086CPU 的转移行为有以下几类。</p><ul><li>只修改 IP 时，称为 <strong>段内转移</strong>，比如：jmp ax。</li><li>同时修改 CS 和 IP 时，称为 <strong>段间转移</strong>，比如：jmp 1000:0。</li></ul><p>由于转移指令对 IP 的修改范围不同，段内转移又分为：<strong>短转移</strong> 和 <strong>近转移</strong>。</p><ul><li>短转移 IP 的修改范围为 -128~127。</li><li>近转移 IP 的修改范围为 -32768~32767。</li></ul><p>8086CPU 的转移指令分为以下几类。</p><ul><li>无条件转移指令(如：jmp)</li><li>条件转移指令</li><li>循环指令(如：loop)</li><li>过程</li><li>中断</li></ul><p>这些转移指令转移的前提条件可能不同，但转移的基本原理是相同的。我们在这一章主要通过深入学习无条件转移指令 jmp 来理解 CPU 执行转移指令的基本原理。</p><h2 id="_9-1-操作符-offset" tabindex="-1">9.1 操作符 offset <a class="header-anchor" href="#_9-1-操作符-offset" aria-label="Permalink to &quot;9.1 操作符 offset&quot;">​</a></h2><p>操作符 offset 在汇编语言中是由编译器处理的符号，它的功能是 <strong>取得标号的偏移地址</strong>。比如下面的程序：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg</span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start: </span></span>
<span class="line"><span>    mov ax, offset start    ;相当于 mov ax,0</span></span>
<span class="line"><span>s: </span></span>
<span class="line"><span>    mov ax, offset s        ;相当于 mov ax,3</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>在上面的程序中，offset 操作符取得了标号 start 和 s 的偏移地址 0 和 3，所以指令：<code>mov ax, offset start</code> 相当于指令 <code>mov ax,0</code>，因为 start 是代码段中的标号，它所标记的指令是代码段中的第一条指令，偏移地址为 0；</p><p><code>mov ax,offset s</code> 相当于指令 <code>mov ax,3</code>，因为 s 是代码段中的标号，它所标记的指令是代码段中的第二条指令，第一条指令长度为 3 个字节，则 s 的偏移地址为 3。</p><h3 id="问题-9-1" tabindex="-1">问题 9.1 <a class="header-anchor" href="#问题-9-1" aria-label="Permalink to &quot;问题 9.1&quot;">​</a></h3><p>有如下程序段，添写两条指令，使该程序在运行中将 s 处的一条指令复制到 s0 处。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg</span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov ax,bx           ;mov ax,bx 的机器码占两个字节</span></span>
<span class="line"><span>    mov si, offset s</span></span>
<span class="line"><span>    mov di, offset s0</span></span>
<span class="line"><span>    _________</span></span>
<span class="line"><span>    _________</span></span>
<span class="line"><span>s0:</span></span>
<span class="line"><span>    nop                 ;nop 的机器码占一个字节</span></span>
<span class="line"><span>    nop</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>思考后看分析。</p><p><strong>分析：</strong></p><p>（1）s 和 s0 处的指令所在的内存单元的地址是多少？cs: offset s 和 cs: offset s0。</p><p>（2）将 s 处的指令复制到 s0 处，就是将 cs: offset s 处的数据复制到 cs: offset s0 处。</p><p>（3）段地址已知在 cs 中，偏移地址 offset s 和 offset s0 已经送入 si 和 di 中。</p><p>（4）要复制的数据有多长？mov ax, bx 指令的长度为两个字节，即 1 个字。</p><p>程序如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg</span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov ax,bx           ;mov ax,bx 的机器码占两个字节</span></span>
<span class="line"><span>    mov si, offset s</span></span>
<span class="line"><span>    mov di, offset s0</span></span>
<span class="line"><span>    mov ax,cs:[si]</span></span>
<span class="line"><span>    mov cs:[di],ax</span></span>
<span class="line"><span>s0: </span></span>
<span class="line"><span>    nop                 ;nop 的机器码占一个字节</span></span>
<span class="line"><span>    nop</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>end s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h2 id="_9-2-jmp-指令" tabindex="-1">9.2 jmp 指令 <a class="header-anchor" href="#_9-2-jmp-指令" aria-label="Permalink to &quot;9.2 jmp 指令&quot;">​</a></h2><p>jmp 为 <strong>无条件转移指令</strong>，可以只修改 IP，也可以同时修改 CS 和 IP。jmp 指令要给出两种信息：</p><ul><li><p>（1）转移的目的地址</p></li><li><p>（2）转移的距离(段间转移、段内短转移、段内近转移)</p></li></ul><p>不同的给出目的地址的方法，和不同的转移位置，对应有不同格式的 jmp 指令。下面几节内容中，以给出目的地址的不同方法为主线，讲解 jmp 指令的主要应用格式和 CPU 执行转移指令的基本原理。</p><h2 id="_9-3-依据位移进行转移的-jmp-指令" tabindex="-1">9.3 依据位移进行转移的 jmp 指令 <a class="header-anchor" href="#_9-3-依据位移进行转移的-jmp-指令" aria-label="Permalink to &quot;9.3 依据位移进行转移的 jmp 指令&quot;">​</a></h2><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jmp short 标号(转到标号处执行指令)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这种格式的 jmp 指令实现的是段内短转移，它对 IP 的修改范围为 -128~127，也就是说，它向前转移时可以最多越过 128 个字节，向后转移可以最多越过 127 个字节。jmp 指令中的“short”符号，说明指令进行的是 <strong>短转移</strong>。jmp 指令中的“标号”是代码段中的标号，指明了指令要转移的目的地，转移指令结束后，CS: IP 应该指向标号处的指令。</p><p>比如：</p><p>【程序 9.1】</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start: </span></span>
<span class="line"><span>    mov ax,0</span></span>
<span class="line"><span>    jmp short s</span></span>
<span class="line"><span>    add ax,1</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    inc ax</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>上面的程序执行后，ax 中的值为 1，因为执行 jmp short s 后，越过了 add ax,1，IP 指向了标号 s 处的 inc ax。也就是说，程序只进行了一次 ax 加 1 操作。</p><p>汇编指令 jmp short s 对应的机器指令应该是什么样的呢？我们先看一下别的汇编指令和其对应的机器指令。</p><table tabindex="0"><thead><tr><th>汇编指令</th><th>机器指令</th></tr></thead><tbody><tr><td>mov ax,0123h</td><td>B8 23 01</td></tr><tr><td>mov ax, ds: [0123h]</td><td>A1 23 01</td></tr><tr><td>push ds: [0123h]</td><td>FF 36 23 01</td></tr></tbody></table><p>可以看到，在一般的汇编指令中，汇编指令中的 idata(立即数)，不论它是表示一个数据还是内存单元的偏移地址，都会在对应的机器指令中出现，因为 CPU 执行的是机器指令，它必须要处理这些数据或地址。</p><p>现在我们在 Debug 中将程序 9.1 翻译成机器码，看到的结果如图 9.1 所示。</p><p><img src="`+b+'" alt="image-20251026200501342"></p>',41)),p(a,{style:{color:"#C0C0C0"}},{default:e(()=>[...s[0]||(s[0]=[l(" 图 9.1 程序 9.1 的机器码 ",-1)])]),_:1}),s[4]||(s[4]=n(`<p>对照汇编源程序，我们可以看到，Debug 将 jmp short s 中的 s 表示为 inc ax 指令的偏移地址 8，并将 jmp short s 表示为 jmp 0008，表示转移到 cs: 0008 处。这一切似乎合理，可是当我们查看 jmp short s 或是 jmp 0008 所对应的机器码，却发现了一些问题。</p><p>jmp 0008(Debug 中的表示)或 jmp short s(汇编语言中表示)所对应的机器码为 EB03，注意，这个 <strong>机器码中竟不包含转移的目的地址</strong>，这意味着，CPU 在执行 EB03 的时候并不知道转移的目的地。那么，CPU 根据什么进行转移呢？它知道转移到哪里呢？</p><p>令人奇怪的是，汇编指令 jmp short s 中，明明是带有转移的目的地址(由标号 s 表示)的，可翻译成机器指令后，怎么目的地址就没了呢？没有了目的地址，CPU 如何知道转移到哪里呢？</p><p>我们把程序 9.1 改写一下，变成下面这样：</p><p><strong>【程序 9.2】</strong></p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg</span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax,0</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span>    jmp short s</span></span>
<span class="line"><span>    add ax,1</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    inc ax</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>我们在 Debug 中将程序 9.2 翻译成机器码，看到的结果如图 9.2 所示。</p><p><img src="`+o+'" alt="image-20251026201327051"></p>',8)),p(a,{style:{color:"#C0C0C0"}},{default:e(()=>[...s[1]||(s[1]=[l(" 图 9.2 程序 9.2 的机器码 ",-1)])]),_:1}),s[5]||(s[5]=n('<p>比较一下程序 9.1 和 9.2 用 Debug 查看的结果，注意，两个程序中的 jmp 指令都要使 IP 指向 inc ax 指令，但是程序 9.1 的 inc ax 指令的偏移地址为 8，而程序 9.2 的 inc ax 指令的偏移地址为 000BH，而两个程序中的 jmp 指令所对应的机器码，<strong>都是 EB 03，这说明 CPU 在执行 jmp 指令的时候并不需要转移的目的地址</strong>。两个程序中的 jmp 指令的转移目的地址并不一样，一个是 cs: 0008，另一个是 cs: 000B，如果机器指令中包含了转移的目的地址的话，那么它们对应的机器码应该是不同的。那么也就是说，CPU 不需要这个目的地址就可以实现对 IP 的修改。</p><p>CPU 只能处理你供给它的东西，jmp 指令的机器码中不包含转移的目的地址，那 CPU 如何知道将 IP 改为多少呢？所以，在 jmp 指令的机器码中，一定包含了某种信息，使得 CPU 可以将它当做改 IP 的依据。</p><p>我们先简单回忆一下 CPU 执行指令的过程(如果你需要更多的回忆，可以复习一下 2.10 节的内容)。</p><ul><li>(1) 从 CS: IP 指向内存单元读取指令，读取的指令进入指令缓冲器;</li><li>(2)(IP)=(IP)+所读取指令的长度，从而指向下一条指令;</li><li>(3) 执行指令。转到 1，重复这个过程。</li></ul><p>按照这个步骤，我们参照图 9.2 看一下，程序 9.2 中 jmp short s 指令的读取和执行过程:</p><ul><li>(1)(CS)= 076AH，(IP)= 0006H，CS: IP 指向 EB 03(jmp short s 的机器码);</li><li>(2)读取指令码 EB 03 送入指令缓冲器;</li><li>(3)(IP)=(IP)+所读取指令的长度 =(IP)+2 = 0008H，CS: IP 指向 add ax,1;</li><li>(4) CPU 执行指令缓冲器中的指令 EB 03;</li><li>(5) 指令 EB 03 执行后，(IP)= 000BH, CS: IP 指向 inc ax。</li></ul><p>从上面的过程中我们看到，CPU 将指令 EB 03 读入后，IP 指向了下一条指令，即 CS: 0008 处的 &quot;add ax, i&quot;，接着执行 EB 03。如果 EB 03 没有对 IP 进行修改的话，那么，接下来 CPU 将执行 add ax,1 可是，CPU 执行的 EB 03 却是一条修改 IP 的转移指令，执行后(IP)= 000BH，CS: IP 指向 inc ax，CS: 0008 处的 add ax,1 没有被执行。</p><p>CPU 在执行 EB 03 的时候是根据什么修改的 IP，使其指向目标指令呢?就是 <strong>根据指令码中的 03</strong>。注意，要转移的目的地址是 CS: 000B，而 CPU 执行 EB 03 时，当前的(IP)= 0008H，如果将当前的 IP 值加 3，使(IP)= 000BH，CS: IP 就可指向目标指令。在转移指令 EB 03 中并没有告诉 CPU 要转移的目的地址，却告诉了 CPU 要转移的位置，即将当前的 IP 向后移动 3 个字节。因为程序 1、2 中的 jmp 指令转移的位移相同，都是向后 3 个字节，所以它们的机器码都是 EB 03。 原来如此，在“jmp short 标号”指令所对应的机器码中，<strong>并不包含转移的目的地址，而包含的是转移的位移</strong>。这个位移，是编译器根据汇编指令中的“标号”计算出来的，具体的计算方法如图 9.3 所示。</p><p><img src="'+d+`" alt="image-20251026201358121"></p><p>实际上，“jmp short 标号”的功能为：<strong>(IP)=(IP)+8 位位移</strong>。</p><p>(1) <strong>8 位位移 = 标号处的地址-jmp 指令后的第一个字节的地址</strong>；</p><p>(2) short 指明此处的位移为 8 位位移；</p><p>(3) 8 位位移的范围为-128~127，用补码表示(如果你对补码还不了解，请阅读附注 2)；</p><p>(4) 8 位位移由编译程序在编译时算出。</p><p>还有一种和“jmp short 标号”功能相近的指令格式，jmp near ptr 标号，它实现的是 <strong>段内近转移</strong>。</p><p>“jmp near ptr 标号”的功能为：(IP)=(IP)+16 位位移。</p><p>(1) 16 位位移 = 标号处的地址-jmp 指令后的第一个字节的地址；</p><p>(2) near ptr 指明此处的位移为 16 位位移，进行的是段内近转移；</p><p>(3) 16 位位移的范围为-32768~32767，用补码表示；</p><p>(4) 16 位位移由编译程序在编译时算出。</p><h2 id="_9-4-转移的目的地址在指令中的-jmp-指令" tabindex="-1">9.4 转移的目的地址在指令中的 jmp 指令 <a class="header-anchor" href="#_9-4-转移的目的地址在指令中的-jmp-指令" aria-label="Permalink to &quot;9.4 转移的目的地址在指令中的 jmp 指令&quot;">​</a></h2><p>前面讲的 jmp 指令，其对应的 <strong>机器指令中并没有转移的目的地址</strong>，而是相对于当前 IP 的 <strong>转移位移</strong>。“<code>jmp far ptr 标号</code>”实现的是 <strong>段间转移</strong>，又称为 <strong>远转移</strong>。功能如下：</p><p>(CS)= 标号所在段的段地址；(IP)= 标号在段中的偏移地址。</p><p>far ptr 指明了指令用标号的段地址和偏移地址修改 CS 和 IP。</p><p>看下面的程序：</p><p>【程序 9.3】</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg</span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax,0</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span>    jmp far ptr s</span></span>
<span class="line"><span>    db 256 dup (0)</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    add ax,1</span></span>
<span class="line"><span>    inc ax</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>在 Debug 中将程序 9.3 翻译成为机器码，看到的结果如图 9.4 所示。</p><p><img src="`+m+'" alt="image-20251026201556488"></p>',29)),p(a,{style:{color:"#C0C0C0"}},{default:e(()=>[...s[2]||(s[2]=[l(" 图 9.4 程序 9.3 的机器码 ",-1)])]),_:1}),s[6]||(s[6]=n(`<p>如图 9.4 中所示，源程序中的 db 256 dup (0)，被 Debug 解释为相应的若干条汇编指令。这不是关键，关键是，我们要注意一下 jmp far ptr s 所对应的机器码：EA 0B 01 6A 07，其中包含转移的目的地址。“0B 01 6A 07”是目的地址在指令中的存储顺序，高地址的“6A 07”是转移的段地址：076AH，低地址的“0B 01”是偏移地址：010BH。</p><p>对于“jmp X 标号”格式的指令的深入分析请参看附注 3。</p><h2 id="_9-5-转移地址在寄存器中的-jmp-指令" tabindex="-1">9.5 转移地址在寄存器中的 jmp 指令 <a class="header-anchor" href="#_9-5-转移地址在寄存器中的-jmp-指令" aria-label="Permalink to &quot;9.5 转移地址在寄存器中的 jmp 指令&quot;">​</a></h2><p>指令格式：jmp 16-bit-reg</p><p>功能：(IP)=(16-bit-reg)</p><p>这种指令我们在前面的内容(参见 2.11 节)中已经讲过，这里就不再详述。</p><h2 id="_9-6-转移地址在内存中的-jmp-指令" tabindex="-1">9.6 转移地址在内存中的 jmp 指令 <a class="header-anchor" href="#_9-6-转移地址在内存中的-jmp-指令" aria-label="Permalink to &quot;9.6 转移地址在内存中的 jmp 指令&quot;">​</a></h2><p>转移地址在内存中的 jmp 指令有两种格式：</p><p>(1) jmp word ptr 内存单元地址(段内转移)</p><p>功能: 从内存单元地址开始存放着一个字, 是转移的目的偏移地址。</p><p>内存单元地址可用寻址方式的任一格方式给出。</p><p>比如, 下面的指令:</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,0123H  </span></span>
<span class="line"><span>mov ds:[0],ax  </span></span>
<span class="line"><span>jmp word ptr ds:[0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>执行后, (IP)= 0123H.</p><p>又比如, 下面的指令:</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, 0123H  </span></span>
<span class="line"><span>mov [bx], ax  </span></span>
<span class="line"><span>jmp word ptr [bx]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>执行后, (IP)= 0123H</p><p>(2) jmp dword ptr 内存单元地址(段间转移)</p><p>功能: 从内存单元地址处开始存放着两个字, 高地址处的字是转移的目的段地址, 低地址处是转移的目的偏移地址。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(CS)=(内存单元地址+2)</span></span>
<span class="line"><span>(IP)=(内存单元地址)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>内存单元地址可用寻址方式的任一格方式给出。</p><p>比如, 下面的指令:</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,0123H  </span></span>
<span class="line"><span>mov ds:[0],ax  </span></span>
<span class="line"><span>mov word ptr ds:[2],0</span></span>
<span class="line"><span>jmp dword ptr ds:[0]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>执行后, (CS)= 0, (IP)= 0123H, CS: IP 指向 0000:0123</p><p>又比如, 下面的指令:</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, 0123H  </span></span>
<span class="line"><span>mov [bx],ax </span></span>
<span class="line"><span>mov word ptr [bx+2],0</span></span>
<span class="line"><span>jmp dword ptr [bx]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>执行后，(CS)= 0，(IP)= 0123H，CS: IP 指向 0000:0123</p><h2 id="_9-a-检测点-9-1" tabindex="-1">9.a 检测点 9.1 <a class="header-anchor" href="#_9-a-检测点-9-1" aria-label="Permalink to &quot;9.a 检测点 9.1&quot;">​</a></h2><p>(1) 程序如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:code</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data segment</span></span>
<span class="line"><span>    ;/*Code Answer*/ </span></span>
<span class="line"><span>data ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>code segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax,data</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span>    jmp word ptr [bx+1]</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>code ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>若要使程序中的 jmp 指令执行后，CS: IP 指向程序的第一条指令，在 data 段中应该定义哪些数据？</p><p>解析：</p><p>本题考察转移地址在内存单元中的 jmp 指令</p><p>指向第一条指令，即让偏移量为 0。</p><p>本题有个有意思的地方，data 段或者 stack 段可以不关联，但是 code 段必须用 assume 关联，否则会编译出错。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>db 0ffh,0,0 ;只需要 2、3 两个字节为零即可，这样[bx+1]=IP=0，即偏移地址为 0，ffh 首位为字母，前面补一个零</span></span>
<span class="line"><span>;用 dw 来定义亦可</span></span>
<span class="line"><span>dw 0,0</span></span>
<span class="line"><span>;用 dd 来定义亦可</span></span>
<span class="line"><span>dd 0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>(2) 程序如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:code</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data segment</span></span>
<span class="line"><span>    dd 12345678H</span></span>
<span class="line"><span>data ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>code segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax,data</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span>    mov [bx],_________</span></span>
<span class="line"><span>    mov [bx+2],_______</span></span>
<span class="line"><span>    jmp dword ptr ds:[0]</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>code ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>补全程序，使 jmp 指令执行后，CS: IP 指向程序的第一条指令。</p><p>解析：</p><p>本题考察转移地址在内存单元中的 jmp <strong>段间转移</strong> 指令</p><p>段间转移要同时设置 cs 和 ip，高地址存放 cs，低地址存放 ip</p><p>对内存单元操作要借助寄存器，所以第一个空不能写 0，要写 bx</p><p>同理，第二个空直接写 cs</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    mov [bx],bx</span></span>
<span class="line"><span>    mov [bx+2],cs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>本题数据段数据为干扰项没有用，但有些题不将数据段单独定义，而是定义在代码段内，这时候相应的地址计算会发生变化，需要留意。</p><p>(3) 用 Debug 查看内存，结果如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2000:1000 BE 00 06 00 00 00 ......</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>则此时，CPU 执行指令：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,2000H</span></span>
<span class="line"><span>mov es,ax</span></span>
<span class="line"><span>jmp dword ptr es:[1000H]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>后，(CS)=?，(IP)=?</p><p>解析：</p><p>和上题一样考察 jmp <strong>段间转移</strong> 指令</p><p>段间转移要同时设置 cs 和 ip，高地址存放 cs，低地址存放 ip</p><p>所以 BE 00 描述的是 ip，06 00 描述的是 cs，按高位低位整理一下，cs = 0006H，ip = 00bEH</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cs=0006H</span></span>
<span class="line"><span>ip=00BEH</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="_9-7-jcxz-指令" tabindex="-1">9.7 jcxz 指令 <a class="header-anchor" href="#_9-7-jcxz-指令" aria-label="Permalink to &quot;9.7 jcxz 指令&quot;">​</a></h2><p><strong>jcxz(Jump if CX Zero</strong>) 指令为 <strong>有条件转移指令</strong>，所有的有条件转移指令都是短转移，在对应的机器码中包含转移的位移，而不是目的地址。对 IP 的修改范围都为：-128~127。</p><p>指令格式：jcxz 标号(如果(cx)= 0，转移到标号处执行)。</p><p>操作：当 (cx)= 0 时，(IP)=(IP)+8 位位移；</p><p>8 位位移 = 标号处的地址 -jcxz 指令后的第一个字节的地址；</p><p>8 位位移的范围为-128~127，用 <strong>补码</strong> 表示；</p><p>8 位位移由编译程序在编译时算出。</p><p>当 (cx)!= 0 时，什么也不做(程序向下执行)。</p><p>我们从 jcxz 的功能中可以看出，“jcxz 标号”的功能相当于：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((cx)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) jmp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">short</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 标号;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  /*用 C 语言和汇编语言进行综合描述，或许更能清楚理解有条件转移指令。*/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="_9-b-检测点-9-2" tabindex="-1">9.b 检测点 9.2 <a class="header-anchor" href="#_9-b-检测点-9-2" aria-label="Permalink to &quot;9.b 检测点 9.2&quot;">​</a></h2><p>补全程序，利用 jcxz 指令，实现在内存 2000H 段中查找第一个值为 0 的字节，找到后，将它的偏移地址存储在 dx 中。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:code</span></span>
<span class="line"><span>code segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax,2000H</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    jmp short s</span></span>
<span class="line"><span>ok:</span></span>
<span class="line"><span>    mov dx,bx</span></span>
<span class="line"><span>    mov ax,4C00h</span></span>
<span class="line"><span>    int 21h</span></span>
<span class="line"><span>code ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>解析：</p><p>思路很简单，一定有一条 <code>jcxz ok</code> 和一条 <code>inc bx</code> 这点很容易想到</p><p>检测字节，要注意 cx 为 16 位寄存器，所以只用一半 cl 或者 ch 读取 [bx]内容即可（另一半要置零，顺序无所谓），不可写成 <code>mov cx,[bx]</code>，这样长度不匹配，检测的变成[bx]和[bx+1]两个字节是否为零了。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:code</span></span>
<span class="line"><span>code segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax,2000H</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov cl,[bx]</span></span>
<span class="line"><span>    mov ch,0</span></span>
<span class="line"><span>    jcxz ok</span></span>
<span class="line"><span>    inc bx</span></span>
<span class="line"><span>    jmp short s</span></span>
<span class="line"><span>ok:</span></span>
<span class="line"><span>    mov dx,bx</span></span>
<span class="line"><span>    mov ax,4C00h</span></span>
<span class="line"><span>    int 21h</span></span>
<span class="line"><span>code ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><h2 id="_9-8-loop-指令" tabindex="-1">9.8 loop 指令 <a class="header-anchor" href="#_9-8-loop-指令" aria-label="Permalink to &quot;9.8 loop 指令&quot;">​</a></h2><p>loop 指令为循环指令，所有的循环指令都是 <strong>短转移</strong>，在对应的机器码中包含转移的位置，而不是目的地址。对 IP 的修改范围都为：-128~127。</p><p>指令格式：loop 标号((cx)=(cx)-1)，如果(cx)≠0，转移到标号处执行。</p><p>操作：</p><p>(1) (cx)=(cx)-1;</p><p>(2) 如果(cx)≠0，(IP)=(IP)+8 位位移。</p><p>8 位位移 = 标号处的地址-loop 指令后的第一个字节的地住；</p><p>8 位位移的范围为-128~127，用补码表示；</p><p>8 位位移由编译程序在编译时算出。</p><p>如果(cx)= 0，什么也不做(程序向下执行)。</p><p>我们从 loop 的功能中可以看出，“loop 标号”的功能相当于：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(cx)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((cx)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) jmp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">short</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 标号;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="_9-c-检测点-9-3" tabindex="-1">9.c 检测点 9.3 <a class="header-anchor" href="#_9-c-检测点-9-3" aria-label="Permalink to &quot;9.c 检测点 9.3&quot;">​</a></h2><p>补全程序，利用 loop 指令，实现在内存 2000H 段中查找第一个值为 0 的字节，找到后，将它的偏移地址存储在 dx 中。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:code</span></span>
<span class="line"><span>code segment</span></span>
<span class="line"><span>start: </span></span>
<span class="line"><span>    mov ax,2000H</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span>s: </span></span>
<span class="line"><span>    mov cl,[bx]</span></span>
<span class="line"><span>    mov ch,0</span></span>
<span class="line"><span>    ________</span></span>
<span class="line"><span>    inc bx</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>ok:</span></span>
<span class="line"><span>    dec bx          ; dec 指令的功能和 inc 相反，dec bx 进行的操作为：(bx)=(bx)-1</span></span>
<span class="line"><span>    mov dx,bx</span></span>
<span class="line"><span>    mov ax,4c00h</span></span>
<span class="line"><span>    int 21h</span></span>
<span class="line"><span>code ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>解析：</p><p>和上一题是类似的，当 cl = 1、ch = 0 时，cx - 1 = 0，所以 cx = 0001H 时，loop 之后正好为 0，跳出循环。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add cl,1</span></span>
<span class="line"><span>;下面这三个答案也可以</span></span>
<span class="line"><span>inc cl</span></span>
<span class="line"><span>add cx,1</span></span>
<span class="line"><span>inc cx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="_9-9-根据位移进行转移的意义" tabindex="-1">9.9 根据位移进行转移的意义 <a class="header-anchor" href="#_9-9-根据位移进行转移的意义" aria-label="Permalink to &quot;9.9 根据位移进行转移的意义&quot;">​</a></h2><p>前面我们讲到：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jmp short 标号  </span></span>
<span class="line"><span>jmp near ptr 标号  </span></span>
<span class="line"><span>jcxz 标号  </span></span>
<span class="line"><span>loop 标号</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>等几种汇编指令，它们对 IP 的修改是根据转移目的地址和转移起始地址之间的位移来进行的。在它们对应的机器码中 <strong>不包含转移的目的地址</strong>，而 <strong>包含的是到目的地址的位移</strong>。</p><p>这种设计，方便了程序段在内存中的浮动装配。</p><p>例如：</p><table tabindex="0"><thead><tr><th>汇编指令</th><th>机器代码</th></tr></thead><tbody><tr><td>mov cx,6</td><td>B9 06 00</td></tr><tr><td>mov ax,10h</td><td>B8 10 00</td></tr><tr><td>s: add ax, ax</td><td>01 C0</td></tr><tr><td>loop s</td><td>E2 FC</td></tr></tbody></table><p><strong>这段程序装在内存中的不同位置都可正确执行</strong>，因为 loop s 在执行时只涉及 s 的位移(-4，前移 4 个字节，补码表示为 FCH)，而不是 s 的地址。如果 loop s 的机器码中包含的是 s 的地址，则就对程序段在内存中的偏移地址有了严格的限制，因为机器码中包含的是 s 的地址，如果 s 处的指令不在目的地址处，程序的执行就会出错。而 loop s 的机器码中包含的是转移的位移，就不存在这个问题了，因为，<strong>无论 s 处的指令的实际地址是多少，loop 指令的转移位移是不变的</strong>。</p><h2 id="_9-10-编译器对转移位移超界的检测" tabindex="-1">9.10 编译器对转移位移超界的检测 <a class="header-anchor" href="#_9-10-编译器对转移位移超界的检测" aria-label="Permalink to &quot;9.10 编译器对转移位移超界的检测&quot;">​</a></h2><p>注意，根据位移进行转移的指令，它们的转移范围受到转移位移的限制，如果在源程序中出现了转移范围超标的问题，在编译的时候，编译器将报错。</p><p>比如，下面的程序将引起编译错误：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:code</span></span>
<span class="line"><span></span></span>
<span class="line"><span>code segment</span></span>
<span class="line"><span>start: </span></span>
<span class="line"><span>    jmp short s</span></span>
<span class="line"><span>    db 128 dup (0)</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov ax, 0ffffh</span></span>
<span class="line"><span>code ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>jmp short s 的转移范围是 -128~127，IP 最多向后移动 127 个字节。</p><p>注意，我们在第 2 章中讲到的形如“jmp 2000:0100”<strong>直接地址跳转格式</strong> 的转移指令，是在 Debug 中使用的汇编指令，汇编编译器比如 MASM 并不认识。如果在源程序中使用，编译时也会报错。</p>`,105))])}const y=i(u,[["render",h]]);export{P as __pageData,y as default};
